    4:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := TRUE;
        EW_R := FALSE;
        T2(IN := TRUE, PT := T#1s);
        IF T2.Q THEN
            State := 5;
        END_IF;

    5:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
        T3(IN := TRUE, PT := T#1s);
