PROGRAM intersection
VAR_OUTPUT
    NS_G : BOOL;
    NS_Y : BOOL;
    NS_R : BOOL;
    EW_G : BOOL;
    EW_Y : BOOL;
    EW_R : BOOL;
END_VAR
VAR
    State : INT;
    green_NS : TON;
    green_EW : TON;
    yellow_NS : TON;
    yellow_EW : TON;
    allred : TON;
END_VAR

CASE State OF
    0 :
        green_NS(IN := TRUE, PT := T#2s);
        yellow_EW(IN := TRUE, PT := T#1s);
        allred(IN := FALSE, PT := T#0s);
        NS_G := green_NS.Q;
        NS_Y := FALSE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := yellow_EW.Q OR allred.Q;
    1 :
        yellow_NS(IN := TRUE, PT := T#1s);
        yellow_EW(IN := TRUE, PT := T#1s);
        allred(IN := FALSE, PT := T#0s);
        NS_G := FALSE;
        NS_Y := yellow_NS.Q;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := yellow_EW.Q OR allred.Q;
    2 :
        allred(IN := TRUE, PT := T#1s);
        allred(IN := TRUE, PT := T#1s);
        allred(IN := TRUE, PT := T#1s);
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := allred.Q;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := allred.Q;
    3 :
        green_EW(IN := TRUE, PT := T#2s);
        yellow_NS(IN := TRUE, PT := T#1s);
        allred(IN := FALSE, PT := T#0s);
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := yellow_NS.Q OR allred.Q;
        EW_G := green_EW.Q;
        EW_Y := FALSE;
        EW_R := FALSE;
    4 :
        yellow_EW(IN := TRUE, PT := T#1s);
        yellow_NS(IN := TRUE, PT := T#1s);
        allred(IN := FALSE, PT := T#0s);
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := yellow_NS.Q OR allred.Q;
        EW_G := FALSE;
        EW_Y := yellow_EW.Q;
        EW_R := FALSE;
    5 :
        allred(IN := TRUE, PT := T#1s);
        allred(IN := TRUE, PT := T#1s);
        allred(IN := TRUE, PT := T#1s);
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := allred.Q;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := allred.Q;
END_CASE;

// Advance state on each tick
State := State + 1 MOD 6;
END_PROGRAM

