    PT_REACT : TIME := T#3s;
END_VAR

IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF StartBatch AND Level >= LIQ_MIN THEN
    CASE State OF
        0:
            IF Level >= LVL_HIGH THEN
                State := 1;
            ELSE
                FillValve := TRUE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            END_IF;
        1:
            IF Level >= LVL_HIGH THEN
                State := 2;
            ELSE
                FillValve := TRUE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            END_IF;
        2:
            IF Temp >= TEMP_SET THEN
                State := 3;
            ELSE
                FillValve := FALSE;
                Heater := TRUE;
                Agitator := TRUE;
                DrainValve := FALSE;
            END_IF;
        3:
            IF Temp >= TEMP_SET AND PT_REACT.TON() THEN
                State := 4;
            ELSE
                FillValve := FALSE;
                Heater := TRUE;
                Agitator := TRUE;
                DrainValve := FALSE;
            END_IF;
            PT_REACT(IN := TRUE, PT := PT_REACT);
        4:
            IF Level <= LVL_LOW THEN
                State := 0;
            ELSE
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := TRUE;
            END_IF;
    END_CASE;
END_IF;

IF State <> 1 OR State <> 4 THEN
    FillValve := FALSE;
END_IF;

IF State <> 2 OR State <> 3 OR State <> 4 THEN
    Heater := FALSE;
    Agitator := FALSE;
END_IF;

IF State <> 3 OR State <> 4 THEN
    DrainValve := FALSE;
END_IF;

END_PROGRAM

