ELSIF StartBatch AND Level >= 10 THEN
    CASE State OF
        0: -- Idle
            IF StartBatch THEN
                State := 1;
            END_IF;
        1: -- Fill
            FillValve := Level < 80;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
