    DrainValve : BOOL;
END_VAR
VAR
    State : INT := 0;
END_VAR

IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF StartBatch AND Level > LIQ_MIN THEN
    CASE State OF
        0:
            IF Level < LVL_HIGH THEN
                State := 1;
                FillValve := TRUE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            ELSE
                State := 2;
                FillValve := FALSE;
                Heater := TRUE;
                Agitator := TRUE;
                DrainValve := FALSE;
            END_IF;
        1:
            IF Level >= LVL_HIGH THEN
                State := 2;
                FillValve := FALSE;
                Heater := TRUE;
                Agitator := TRUE;
                DrainValve := FALSE;
            END_IF;
        2:
            IF Temp >= TEMP_SET THEN
                State := 3;
                FillValve := FALSE;
                Heater := TRUE;
                Agitator := TRUE;
                DrainValve := FALSE;
            END_IF;
        3:
            IF Ticks >= PT_REACT THEN
                State := 4;
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            END_IF;
        4:
            IF Level <= LVL_LOW THEN
                State := 0;
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            ELSE
                State := 4;
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := TRUE;
            END_IF;
    END_CASE;
END_IF;

// Ensure fill and drain valves never open together
IF FillValve AND DrainValve THEN
    FillValve := FALSE;
    DrainValve := FALSE;
END_IF;

// Ensure heater and agitator never run without enough liquid
IF (Heater OR Agitator) AND Level < LIQ_MIN THEN
    Heater := FALSE;
    Agitator := FALSE;
END_IF;
END_PROGRAM

