    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF StartBatch AND State = 0 THEN
    State := 1;
ELSIF State = 1 AND Level >= LVL_HIGH THEN
    State := 2;
ELSIF State = 2 AND Temp >= TEMP_SET AND Level >= LIQ_MIN THEN
    State := 3;
ELSIF State = 3 AND PT_REACT.TON() THEN
    State := 4;
ELSIF State = 4 AND Level <= LVL_LOW THEN
    State := 0;
END_IF;

CASE State OF
    0: // Idle
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
    1: // Fill
        FillValve := TRUE;
        Heater := FALSE;
