        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
        PT_REACT(IN := TRUE, PT := PT_REACT);
    4: // Drain
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := TRUE;
END_CASE;

IF FillValve AND DrainValve OR Level < LIQ_MIN THEN
    State := 0;
    FillValve := FALSE;
