PROGRAM star_delta
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    MainK : BOOL;
    StarK : BOOL;
    DeltaK : BOOL;
END_VAR
VAR
    State : INT := 0;
    PT_STAR : TIME := T#3s;
    StarTimer : TON;
END_VAR

CASE State OF
    0: // Off
        IF StartPB AND EStop THEN
            State := 1;
            MainK := TRUE;
            StarK := TRUE;
            DeltaK := FALSE;
        END_IF;

    1: // Star
        IF NOT EStop OR StopPB THEN
            State := 0;
            MainK := FALSE;
            StarK := FALSE;
            DeltaK := FALSE;
        ELSIF StarTimer.Q THEN
            State := 2;
            MainK := TRUE;
            StarK := FALSE;
            DeltaK := TRUE;
        ELSE
            StarTimer(IN := TRUE, PT := PT_STAR);
        END_IF;

    2: // Delta
        IF NOT EStop OR StopPB THEN
            State := 0;
            MainK := FALSE;
            StarK := FALSE;
            DeltaK := FALSE;
        END_IF;
END_CASE;

// Ensure StarK and DeltaK never both true at the same time
StarK := StarK AND NOT DeltaK;
DeltaK := DeltaK AND NOT StarK;

END_PROGRAM

