PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT := 0;
    T1 : TON;
    T2 : TON;
END_VAR

IF NOT EStop THEN
    State := 0;
    C1 := FALSE;
    C2 := FALSE;
    C3 := FALSE;
ELSIF StartPB AND NOT StopPB THEN
    CASE State OF
        0:
            IF T1.Q THEN
                State := 1;
                C3 := TRUE;
                T2(IN := TRUE, PT := T#2s);
            ELSE
                T1(IN := TRUE, PT := T#2s);
            END_IF;
        1:
            IF T2.Q THEN
                State := 2;
                C2 := TRUE;
                T1(IN := TRUE, PT := T#2s);
            END_IF;
        2:
            IF T1.Q THEN
                State := 3;
                C1 := TRUE;
            END_IF;
    END_CASE;
END_IF;

END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT;
END_VAR

CASE State OF
    0:
        IF StartPB AND NOT EStop THEN
            State := 1;
        END_IF;
    1:
        IF T#2s.Q THEN
            State := 2;
        END_IF;
    2:
        IF T#2s.Q THEN
            State := 3;
        END_IF;
    3:
        IF StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;

T3(IN := (State >= 1), PT := T#2s);
T4(IN := (State >= 2), PT := T#2s);

C3 := (State >= 1);
C2 := (State >= 2);
C1 := (State = 3);
END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    PT_SEQ : TIME := T#2s;
END_VAR

CASE State OF
    0:
        IF StartPB AND NOT EStop THEN
            State := 1;
        END_IF;
    1:
        IF StartPB AND NOT EStop THEN
            C3 := TRUE;
            State := 2;
        END_IF;
    2:
        IF StartPB AND NOT EStop THEN
            C3 := TRUE;
            C2 := TRUE;
            IF TON_C3_2.Q THEN
                State := 3;
            END_IF;
        END_IF;
    3:
        IF StartPB AND NOT EStop THEN
            C3 := TRUE;
            C2 := TRUE;
            C1 := TRUE;
            IF TON_C3_3.Q THEN
                State := 3;
            END_IF;
        END_IF;
END_CASE;

IF NOT EStop OR StopPB THEN
    State := 0;
    C1 := FALSE;
    C2 := FALSE;
    C3 := FALSE;
END_IF;

IF State >= 1 THEN
    TON_C3_2(IN := TRUE, PT := PT_SEQ);
END_IF;

IF State >= 2 THEN
    TON_C3_3(IN := TRUE, PT := PT_SEQ);
END_IF;
END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT := 0;
END_VAR
VAR CONSTANT
    PT_SEQ : TIME := T#2s;
END_VAR

IF NOT EStop THEN
    CASE State OF
        0:
            IF StartPB AND StopPB THEN
                State := 0;
            ELSIF StartPB AND NOT StopPB THEN
                State := 1;
            END_IF;
        1:
            IF StartPB AND StopPB THEN
                State := 0;
            ELSIF StartPB AND NOT StopPB AND TON_PT_C3.Q THEN
                State := 2;
            END_IF;
        2:
            IF StartPB AND StopPB THEN
                State := 0;
            ELSIF StartPB AND NOT StopPB AND TON_PT_C2.Q THEN
                State := 3;
            END_IF;
        3:
            IF StartPB AND StopPB OR TON_PT_C1.Q THEN
                State := 0;
            END_IF;
    END_CASE;

    TON_PT_C3(IN := TRUE, PT := PT_SEQ);
    TON_PT_C2(IN := TRUE, PT := PT_SEQ);
    TON_PT_C1(IN := TRUE, PT := PT_SEQ);

    C1 := State >= 3;
    C2 := State >= 2;
    C3 := State >= 1;
ELSE
    C1 := FALSE;
    C2 := FALSE;
    C3 := FALSE;
    State := 0;
END_IF;

END_PROGRAM

