    T2 : TON;
END_VAR

IF NOT EStop OR StopPB THEN
    State := 0;
    C1 := FALSE;
    C2 := FALSE;
    C3 := FALSE;
ELSIF StartPB AND State = 0 THEN
    State := 1;
    T1(IN := TRUE, PT := T#2s);
    C1 := FALSE;
    C2 := FALSE;
    C3 := TRUE;
ELSIF T1.Q AND State = 1 THEN
    State := 2;
    T2(IN := TRUE, PT := T#2s);
    C1 := FALSE;
    C2 := TRUE;
    C3 := TRUE;
ELSIF T2.Q AND State = 2 THEN
    State := 3;
    C1 := TRUE;
    C2 := TRUE;
    C3 := TRUE;
END_IF;

CASE State OF
    0: C1 := FALSE; C2 := FALSE; C3 := FALSE;
    1: C1 := FALSE; C2 := FALSE; C3 := TRUE;
    2: C1 := FALSE; C2 := TRUE; C3 := TRUE;
    3: C1 := TRUE; C2 := TRUE; C3 := TRUE;
END_CASE;

END_PROGRAM

