    END_CASE;

    CASE State OF
        0:
            C1 := FALSE;
            C2 := FALSE;
            C3 := FALSE;
        1:
            C1 := FALSE;
            C2 := FALSE;
            C3 := TRUE;
        2:
            C1 := FALSE;
            C2 := TRUE;
            C3 := TRUE;
        3:
            C1 := TRUE;
            C2 := TRUE;
            C3 := TRUE;
    END_CASE;
ELSE
    C1 := FALSE;
    C2 := FALSE;
    C3 := FALSE;
    State := 0;
END_IF;
