            IF StopPB OR T#2s > PT_SEQ THEN
                State := 0;
            END_IF;
    END_CASE;
ELSE
    State := 0;
END_IF;

C1 := FALSE;
C2 := FALSE;
C3 := FALSE;
IF State >= 1 THEN C3 := TRUE END_IF;
